# Ronde 17: meer volken, uiterlijk, extreme en diverse seksualiteit, walgingsschaal 1-10, wormnavigators (idempotent)
import sqlite3,re,shutil,os
if not os.path.exists('canon_backup_ronde17.db'): shutil.copy('canon.db','canon_backup_ronde17.db')
c=sqlite3.connect('canon.db');n={'canon':0}
GRENS=' Alles tussen volwassen (18+), sprekende, instemmende wezens; geen minderjarigen, geen dieren; dwang alleen als gelabeld donker thema tussen volwassenen.'
def add(code,cat,ond,feit,reden,refs,**kw):
  if c.execute("select 1 from canon where code=?",(code,)).fetchone(): return
  cols=['categorie','onderwerp','feit','status','reden','hangt_samen_met','ronde','code','verwijst_naar']+list(kw)
  vals=[cat,ond,feit,'voorlopig','Ronde 17: '+reden,refs,17,code,refs]+list(kw.values())
  c.execute(f"insert into canon({','.join(cols)}) values({','.join('?'*len(cols))})",vals);n['canon']+=1
# ---------- D eerst: omzetting 1-5 -> 1-10 (eenmalig) ----------
MAP={0:1,1:2,2:4,3:6,4:7,5:9}
if not c.execute("select 1 from logboek where wat like 'Ronde 17 walgingsschaal-omzetting%'").fetchone():
  rows=c.execute("select id,afstoting,feit from canon where afstoting is not null").fetchall()
  for i,a,f in rows:
    nf=re.sub(r'(fstoting:?\s*)(\d)/5',lambda m:f"{m.group(1)}{MAP[int(m.group(2))]}/10",f)
    nf=re.sub(r'(fstoting )(\d)(?![/\d])',lambda m:f"{m.group(1)}{MAP[int(m.group(2))]}/10",nf)
    c.execute("update canon set afstoting=?,feit=? where id=?",(MAP[a],nf,i))
  c.execute("insert into logboek(datum,wat) values('2026-10-30',?)",(f"Ronde 17 walgingsschaal-omzetting: {len(rows)} afstoting-velden (LICH, NAV, KOE, DEG, VOLK, FUNC, PLEK) omgezet van 1-5 naar 1-10 volgens 1→2, 2→4, 3→6, 4→7, 5→9; tekstvermeldingen 'x/5' mee omgezet. Nooit 0.",))
add('REGEL-walgingsschaal','Genre','Walgingsschaal 1-10',"Het veld afstoting meet walging op 1-10 en is nooit 0: body horror is altijd afstotelijk. 1-2 subtiel vreemd (iets klopt niet); 3-4 ongemakkelijk (men kijkt weg); 5 duidelijk walgelijk; 6-7 misselijkmakend (geur, vocht, zichtbaar verval); 8-9 extreem (het lichaam is geen mens meer, rotting, parasieten, levend verval); 10 de grens van het denkbare (alleen op enkele plekken, zoals Ves-Anath en de diepwormen). Aantrekking blijft een apart veld 0-5 met aantrekking_bron (macht, functie, fetisj, angstlust); de vervorming zelf is nooit de bron. Oude waarden 1-5 zijn in ronde 17 omgezet: 1→2, 2→4, 3→6, 4→7, 5→9.","schaal vastgelegd","REGEL-harde-grenzen;FUNC-overzicht")
# ---------- VOOR nieuw ----------
