# slug,naam,nietmenselijk,functie-tekst,funccodes,oorsprong,geslacht,cultuur,religie,zaad/orde,regio,huizen/conflict,plekken,afstoting,regrefs
V=[('kluwer','De Kluwers (korfvolk)','insectoïde kolonie',
 'Korfgeneesheren en zijdeleveranciers: hun honingwas geneest zaadslijtage en Leegteziekte tijdelijk; de Orde koopt hem voor tempelstieren, Varenne voor de Zaadbeurs. Zonder Kluwers sterven de stallen sneller.','ECO;VOORT;PROD',
 'Ouder dan de mensen, maar de Zegel maakte hen tot wat ze zijn: hun mannetjes stierven net als mensenjongens, dus werd de korf de oplossing. Eén Broedmoeder slaat zaad van veel mannetjes op en mengt het zelf; zo kennen zij geen inteelt. Het is de oplossing die de Orde nooit kon nabootsen.',
 'Per korf één Broedmoeder (3 meter, onbeweeglijk), enkele honderden volwassen werksters die alleen in de korfgeur vruchtbaar worden, en een tiental darren (mannetjes) die na hun paartijd sterven. Eieren in waskamers.',
 'Geen ik, wel een korf: beslissingen via geur. Werksters praten in koor. Ze vinden mensen eenzaam.','De Broedmoeder is god zolang ze leeft; bij haar dood kiest de korf de werkster die het eerst ruikt als moeder.',
 'Ze bewonderen het Deelwet-systeem als een slechte korf. De Orde huurt Kluwers als stalverzorgsters; heimelijk willen Kluwers menselijke gaven-mannen als darren.',
 'Groenmuil, in holle reuzenbomen en kalkheuvels','Varenne (koper van honingwas); conflict met de Myrrhen om bosgrond en met de Orde die hun geheim wil stelen.','PLEK-LICH-fokstallen;PLEK-LICH-zaadbeurs',7,'REG-groenmuil;HUI-varenne;ORDE-orde;KOE-tempelstier'),
('myrrhen','De Myrrhen (sporenvolk)','schimmel-symbiose',
 'Levend medicijn en geheugenbed: hun schimmelnet onthoudt alles wat erin sterft en kan de Leegte vertragen. De Stille Zusters slaan er bewijs in op; de Orde verbrandt hun bossen.','INFO;HECHT;ECO',
 'Gevolg van de Leegte: na de Pest van 470 lieten stervende vrouwen en mannen op de Nevel-eilanden zich door een veenzwam overgroeien om niet leeg te vallen. De zwam hield hen in leven; hun kinderen worden met sporen geboren.',
 'Ongeveer gelijk aantal mannen en vrouwen, want de zwam beschermt mannelijke vruchten tegen de Zegel. Ze planten zich voort met lichaam en spore: de baby krijgt bij geboorte een spore-inenting. Dat is hun grootste geheim.',
 'Traag, gemeenschappelijk, geduldig; ze leven in vochtige veenhallen en delen dromen via het net.','De Grote Draad: alles wat leeft is één net; sterven is ingeweven worden.',
 'Als de Orde wist dat de zwam jongens beschermt, zou ze hen oogsten of uitroeien; daarom handelen ze alleen via Mirre. Hun zaad geeft geen gave.',
 'Nevel-eilanden, veenhallen','Mirre (smokkel van medicijn); vijand van de Orde; Stille Zusters als bondgenoot.','PLEK-LICH-nevel;PLEK-LICH-stille-klooster;PLEK-LICH-leegtehuis',8,'HUI-mirre;ORDE-orde;LICH-leegteziekte'),
('oevrin','De Oevrin (slikvolk)','amfibisch',
 'Onderwatersmokkelaars en levende sluizen: zij trekken boten door het slik van de Zoutkust en kennen de geheime watergangen. Zonder hen geen smokkel van zaad en vrouwen buiten de registers.','ECO;INFO',
 'Ouder dan de mensen: een moerasvolk met uitwendige bevruchting, waardoor de Zegel hen nauwelijks raakte (hun kuit groeit buiten de baarmoeder, buiten bereik van de Zegel). Daarom hebben ze nog evenveel mannen als vrouwen.',
 'Evenveel mannen als vrouwen. Vrouwen leggen kuitsnoeren in paaipoelen, mannen bevruchten in het water; volwassenen verzorgen de broedpoel samen. Geen vaderschap, alleen een poel.',
 'Losse, zingende clans; kwaken in akkoorden; eerlijk en ongeduldig met regels.','Ze vereren de Getijdenmoeder; alles wat de zee terugneemt is heilig.',
 'Het zaadsysteem is voor hen onbegrijpelijk; ze lachen om de Orde. Mirre gebruikt hen; de Orde wil hun poelen droogleggen omdat ze vrije mannen hebben.',
 'Zoutkust, slikvelden en mangroven','Mirre (bondgenoot, uitbuiter); conflict met Kaldra dat dijken legt.','PLEK-LICH-mirre-havens;PLEK-RAND-wrakkust',6,'REG-zoutkust;HUI-mirre;HUI-kaldra'),
('tharn','De Tharn (reuzen)','gigant (3-5 meter)',
 'Levende wallen en dijkbouwers: ze bouwden de dijken van de Overvloed en bewaken nu de Amberpas voor Kaldra. Één Tharn houdt een poort tegen een leger. Zonder hen valt de pas voor Kharvos.','MIL;ECO',
 'Ouder dan de mensen; de Zegel trof hen het hardst: een Tharn-vrouw krijgt eens per vijftig jaar een kind, bijna altijd een meisje. Ze sterven langzaam uit en weten het.',
 'Nog 1 man op 40; minder dan 900 Tharn in totaal. Draagtijd drie jaar.','Trage rouw, eer, steenliederen van uren. Ze houden verhalen bij in hun eigen huid (littekens).','Ze geloven dat de wereld een reus is die slaapt; de Zegel is zijn nachtmerrie.',
 'Kaldra betaalt hen in zaad van gaven-mannen, in de hoop op Tharn-kinderen; dat werkt nooit en vergiftigt hun vrouwen (wrijving). Tharn-zaad geeft mensen geen gave maar wel uren dierlijke kracht.',
 'Ambergaard, Amberpas','Kaldra (opdrachtgever en schuldeiser); vijand van de Karrûk.','PLEK-LICH-slagveld-amberpas;PLEK-LICH-kaldra-kamp',5,'REG-ambergaard;HUI-kaldra;VOLK-karrûk'),
('orrim','De Orrim (steenvolk)','steenachtig, kristallijn',
 'Levende Sterrensteen-groeven en zegelankers: in hun lichaam groeit Sterrensteen. De Orde heeft dat steen nodig voor merk, inkt en Zegel; daarom worden Orrim heimelijk "geoogst".','REL;ECO;ID',
 'Ouder dan de Zegel: woestijnwezens die Sterrensteen-stof inademden tot ze erdoor werden doorgroeid. De vrouwen die de Zegel legden, gebruikten hun steen. Dat staat in geen enkele annaal.',
 'Geslachtloos tot ze paren; dan wordt de ene drager en de andere zaaier. Ze planten zich voort door slijpen: een afgeslepen fragment wordt met de mineralen van de partner bevrucht en groeit in tien jaar tot een volwassen Orrim.',
 'Zwijgzaam, eeuwenoud, juridisch: elke ruzie wordt met slijpen beslecht.','Ze vereren de eerste steen; zij weten dat de Zegel van hun voorouders gemaakt is.',
 'Doelwit van de Orde (steenoogst) en van de Dhurn (concurrenten om Sterrensteen). Qesh beschermt hen tegen betaling.',
 'Rosse Woestijn, rond Qesh','Dhurn (rivalen), Qesh (beschermer), Orde (jager).','PLEK-LICH-qesh;PLEK-LICH-bloedkerker',6,'REG-rosse;VOLK-dhurn;ORDE-orde;VOLK-ishvar'),
('skerra','De Skerra (vleugelvolk)','gevleugeld, holle botten',
 'Koeriers en luchtwacht: zij vliegen berichten, registers en lekmeldingen over de Ysmer in uren. Wie de Skerra heeft, heeft de snelste informatie; de Orde en Varenne vechten om hun trouw.','INFO;MIL;POL',
 'Gevolg van de Vonk: in de Vonktijd lieten vonkkoningen vrouwen met gaven-zaad en kliffvogel-bloedriten veranderen; de Zegel maakte die verandering erfelijk. Ze zijn het enige volk dat mensen zelf maakten.',
 '1 man op 12; vrouwen groter en dominant. Eieren in klifnesten, door beide ouders bebroed; volwassen pas met 18 jaar, dan de eerste vlucht.',
 'Snel, trots, wreed in eer; een Skerra die niet meer vliegt, telt niet.','Ze vereren de Wind en de Val: wie valt en zich vangt, wordt herboren.',
 'Ze verkopen hun mannen niet; de Orde vindt dat schandelijk en wil hun mannen registreren. Morvane-ir wil hun vleugels voor zijn hof.',
 'Kliffen van Hoogvrouwe en de Ysmer-rotsen','Orde (opdrachtgever en dreiging), Varenne (koper van nieuws), Morvane-ir (jager).','PLEK-LICH-pelgrimsweg;PLEK-LICH-donker-hof',4,'REG-hoogvrouwe;ORDE-orde;HUI-varenne;PER-morvane'),
('ves-lethi','De Ves-Lethi (vormwisselaars)','vormveranderend, tweeslachtig',
 'Spionnen en, veel gevaarlijker, de enigen die van vrouw in man kunnen veranderen: een Ves-Lethi in mannelijke fase is vruchtbaar. Daarmee kunnen zij het mannentekort omzeilen; dat bedreigt het hele zaadsysteem en de macht van de Orde.','VOORT;INFO;DIPLO',
 'Gevolg van de zegelschaduw: in Kharvos-grensdorpen werden lichamen instabiel. Zo kwam er een volk dat elke maancyclus van geslacht kan wisselen en, met moeite, van gezicht.',
 'Iedereen is beide; elke maancyclus kiest het lichaam (of de wil) een fase. Wie te vaak wisselt verliest zijn eigen gezicht. Kinderen worden geboren zonder vast geslacht. Zij nemen nooit de gedaante aan van een kind of dier: dat breekt hun lichaam en hun wet.',
 'Wantrouwig, theatraal, lid van wie hen betaalt; namen wisselen mee met de vorm.','De Lege Spiegel: er is geen echt ik, alleen keuze.',
 'De Orde jaagt op hen als ketters; Kharvos gebruikt hen als spionnen in tempels; zij kunnen als nep-gaven-man door een Ontvangst gaan, maar geven geen gave.',
 'Grensgebied tussen Kharvos en de Stille Zusterschappen','Kharvos (opdrachtgever), Orde (jager), Stille Zusters (wantrouwige bondgenoot).','PLEK-LICH-zegelschaduw;PLEK-RAND-schaduwvlakte',7,'REG-kharvos;REG-stille;ORDE-orde'),
]
for s,nm,lb,fn,fc,oor,gesl,cult,rel,zo,reg,hc,pl,af,rr in V:
  f=(f"Lichaamsbouw: {lb} (niet-menselijk). Functie: {fn} Oorsprong: {oor} Geslachtsverhouding en voortplanting: {gesl} Cultuur: {cult} Religie: {rel} Zaadsysteem en Orde: {zo} Regio: {reg}. Huizen en conflictlijnen: {hc} Plekken: {pl.replace(';',', ')}. Afstoting {af}/10. Uiterlijk: zie UIT-VOLK-{s}; seksualiteit: SEKS-VOLK-{s}-kern."+GRENS)
  refs=';'.join([rr,pl]+['FUNC-'+x for x in fc.split(';')]+[f'UIT-VOLK-{s}',f'SEKS-VOLK-{s}-kern'])
  add('VOLK-'+s,'Volken',nm,f,'nieuw volk, functie eerst',refs,functie=fc,afstoting=af,aantrekking_bron={'kluwer':'functie (geneeswas), korfgenot','myrrhen':'sporenroes, gedeelde droom','oevrin':'vrije mannen, slijmlust','tharn':'maat en kracht','orrim':'Sterrensteen-macht, versteening','skerra':'vlucht, trots, gevaar','ves-lethi':'elke gewenste gedaante; angstlust'}[s],aantrekking={'kluwer':2,'myrrhen':2,'oevrin':3,'tharn':3,'orrim':2,'skerra':4,'ves-lethi':4}[s])
# ---------- B: uiterlijk alle 14 ----------
U={'aelthir':('VOLK-aelthir','Lang (2 m) en smal, lange vingers met een extra kootje, trage gratie.','Doorschijnende huid waarin aderen en hartslag kloppen; zilvergrijs haar tot de knieën; ogen zonder wit, als zwart glas.','1,90-2,10 m, licht.','Bij hoge ouderdom wordt de huid zo dun dat organen zichtbaar zijn.','Geur van koud ijzer en gedroogde bloemen; stem laag en zeer langzaam; bewegen zonder geluid.','Lagen gazen gewaden, zilveren draden in het haar met het aantal eeuwen.','Eilandlijnen bleker, bergaelthir donkerder met grijze ogen.','Vrouwen langer en smaller, mannen met zichtbare hartslag in de hals; beide zonder lichaamshaar.','Bij inteelt: glazen botten, huid die scheurt bij aanraking; in de zegelschaduw beginnen ze te vergeten.','Je ziet eerst het hart, dat tegen het licht klopt. Dan pas het gezicht, jong en eeuwenoud tegelijk. Ze kijken alsof ze je al begraven hebben.'),
'karruk':('VOLK-karrûk','Breed, zwaar gespierd, nek als een stier, korte dikke vingers.','Rossig tot koperen huid vol ingekerfde rouwtekens, kookhuid die blaast bij woede; zwart stug haar; oranje ogen.','1,80-2,10 m, 120 kg.','Kookhuid: blaren die opspringen en korsten; oudere krijgers met verkoolde handen.','Geur van rook en zweet; brullende stem; bewegen in uitvallen.','Leer, botten, littekens als sieraad; gevijlde tanden.','Kampstammen verschillen in kleur van littekens.','Vrouwen even breed en vaak groter in rang; mannen met meer kookhuid.','In de zegelschaduw: kookkoppen, hoofden die blijven gloeien; bij inteelt: botten die doorbreken.','Hitte komt eerst, als van een oven. Dan de littekens, elk een dode. Hij lacht met geslepen tanden.'),
'dhurn':('VOLK-dhurn','Gedrongen, 1,40 m, enorm sterke armen, korte benen.','Steenhuid op knieën, ellebogen en handen; zwarte nagels; vaak bloedspiegel-ogen die in het donker gloeien; baarden bij beide geslachten.','1,30-1,50 m, zwaar.','Gezwellen van steenhuid bij oude mijnwerkers.','Geur van zwavel en heet water; stemmen als grind; tred zwaar en zeker.','Gildeleer, Sterrensteen-splinters in de baard als rang.','Diepe clans grijzer, hoogland-clans bruiner.','Vrouwen met gevlochten baard, mannen kaal.','Bij inteelt: steenhuid over de ogen (blindheid); zeldzaam omdat het gilde streng is.','Klein, breed, met ogen die in het donker oplichten als kooltjes. Hun handen voelen als ruwe steen. Ze tellen alles wat je draagt.'),
'saelmor':('VOLK-sael-mor','Slank, lange armen, platte voeten met vliezen tussen de tenen.','Zoutkorsten op schouders en dijen, kieuwspleten in de hals, zeegroene ogen; huid koel en vochtig; haar als zeewier, groen-zwart.','1,60-1,80 m.','Kieuwen die rotten op het land; zoutzweren.','Geur van zee en wier; zingende stem met klikgeluid; op land wat stuntelig, in water snel.','Tatoeages van stromingen, schelpen, bijna naakt aan boord.','Per vloot andere tatoeage.','Mannen zeldzaam (1 op 20), zwaarder gebouwd, vaak met dikkere zoutkorst.','Bij inteelt en zegelwater: half oplossende huid (zoutlijken).','Ze ruikt naar zout en iets wat al te lang op het strand ligt. De kieuwen in haar hals ademen mee als ze lacht. Op het land lijkt ze een vis die niet weet hoe ze moet vallen.'),
'grauwen':('VOLK-grauwen','Ieder lichaam anders: vergroeide vingers, botgroei op schouders, scheve ruggen.','Dubbele irissen, witte vlekken, grauwe huid; dun haar.','1,40-1,90 m.','De zichtbare gevolgen van inteelt: extra kootjes, geen oorschelpen, gesloten oogleden.','Geur van zalf; zachte stemmen; ze bewegen voorzichtig om pijn te sparen.','Grauwe doeken die alles behalve de ogen bedekken.','Enorm: geen twee gelijk.','Vrouwen en mannen even vervormd; mannen iets talrijker dan bij mensen.','Hun normaal is de inteelt zelf; in de zegelschaduw verergert alles.','Je ziet alleen ogen tussen grauwe doeken, maar met twee irissen per oog. Als de doek valt, kijkt iedereen weg. Behalve zij: zij kijken terug.'),
'ishvar':('VOLK-ishvar','Lang, pezig, woestijnbouw.','Donker gelooid, lange vlechten, gouden oorringen als gelofte; heldere bruine ogen; geen enkel zegelteken.','1,70-1,90 m.','Geen; dat is het vreemde: ze zijn het enige volk zonder zegeltekens.','Geur van hars en kameelvet; heldere, zingende stem; rustige pas.','Indigo sluiers, goud, henna.','Stammen per oase.','Mannen en vrouwen even talrijk; mannen dragen meer goud.','Bij contact met gaven-zaad verbranden hun vrouwen: huid die blaast waar het zaad kwam.','Ze valt op doordat er niets aan haar is. Geen merk, geen gloed, geen litteken. In Velmara is dat het meest naakte lichaam dat er bestaat.'),
'vathren':('VOLK-vathren','Mager, gespannen, alsof ze altijd luisteren.','Gloeiende littekens als zegelpatronen, aderen van zegellicht; vaak doof; ogen met lichtpuntjes.','1,70-1,90 m.','Zegellicht dat door de huid lekt bij opwinding of angst.','Geur van ozon; ze spreken met handen en hartslag; bewegen schokkerig bij lekpieken.','Ze dragen weinig om de littekens te tonen; zwarte banden om de pols.','Lekkinderen (na 750) met fellere gloed.','Oorspronkelijk alleen mannen; vrouwelijke gezellen krijgen langzaam zelf littekens.','Hoe dichter bij Ves-Anath, hoe feller en pijnlijker de gloed.','In het donker zie je hem eerst aan zijn aderen, die licht geven. Hij hoort je niet, maar hij voelt je hart. Hij weet dat je bang bent voor je het zelf weet.'),
'kluwer':('VOLK-kluwer','Insectoïde: zes ledematen (vier poten, twee grijparmen), gesegmenteerd achterlijf, chitinepantser.','Glanzend bruin-amber chitine, vliezige vleugelresten, facetogen in honingkleur, voelsprieten.','Werksters 1,5 m, darren 1,2 m, Broedmoeder 3 m lang en log.','Broedmoeders zijn een opgezwollen eierbuik met een klein vrouwelijk bovenlijf.','Geur van zoete honing en mierenzuur; ze praten in koor met klikken; bewegen tegelijk.','Wassieraden, gekleurde honingstrepen als korfteken.','Per korf een andere kleur en geur.','Werksters slank, darren vleugeliger en kort levend.','Bij een stervende korf: chitine dat zacht wordt en rot; zonder Broedmoeder worden werksters wild.','Je hoort hen eerst: tien stemmen die één zin spreken. Facetogen weerkaatsen je honderd keer. Ze ruiken naar honing en naar iets wat zuur is.'),
'myrrhen':('VOLK-myrrhen','Menselijke vorm, maar doorgroeid met schimmel: zwammen als kragen op schouders en ruggengraat.','Huid grauwwit met lichtgevend mycelium eronder, haar vervangen door fijne schimmeldraden; ogen melkwit met sporen erin.','1,50-1,80 m, licht en sponsachtig.','Plaatjeszwammen die uit de rug groeien en sporen uitblazen; open plekken waar de schimmel vlees heeft vervangen.','Geur van natte bosgrond en rotting, ook zoet; zacht fluisterende stem; traag.','Geen kleding nodig; vochtige doeken, mos.','Ouderen meer schimmel dan mens.','Mannen met fellere sporenkragen, vrouwen met lichtgevend mycelium.','Bij inteelt van de zwam (te weinig nieuwe sporen): lichaam dat van binnen vergaat.','Ze ruikt naar een bos na de regen en naar wat erin ligt te rotten. Onder haar huid lichten draden als sterren. Als ze ademt zie je een wolkje sporen.'),
'oevrin':('VOLK-oevrin','Amfibisch: lange, slanke ledematen met vliezen, geen nek, brede mond, rekbare keelzak.','Gladde, slijmerige huid in olijfgroen en gevlekt geel, geen haar, uitpuilende goudogen met spleetpupil.','1,60-1,90 m.','Keelzak die tot een bal kan zwellen; slijm dat bij opwinding dikker wordt.','Geur van slik en zout; kwakende, zingende stem in akkoorden; springend.','Kralen, gevlochten riet, verder naakt.','Zoutkust-clans geler, mangrove-clans groener.','Mannen met grotere keelzak en duimkussens om vast te houden; vrouwen voller met kuitzakken.','Op het droge: barstende huid; bij vervuild water: zweren en blinde ogen.','Haar ogen staan te ver uit elkaar en knipperen van onder naar boven. Haar huid glanst en laat slijm achter op je hand. Ze kwaakt een lied als ze lacht.'),
'tharn':('VOLK-tharn','Reuzen van 3-5 meter, zware botten, handen als schoppen.','Grijsbruine, bijna leerachtige huid vol littekens (hun archief), mosachtig haar, kleine diepliggende ogen.','3-5 m, meer dan een ton.','Groeiende botten die nooit stoppen; oude Tharn krom onder hun eigen gewicht.','Geur van aarde en oud zweet; stem die je in je borst voelt; langzaam, elke stap een schok.','Huiden, kettingen van dijkstenen, ingekerfde verhalen.','Pas-Tharn groter, dijk-Tharn zwaarder.','Vrouwen groter dan mannen; mannen zeldzaam en met littekens van gevechten.','Kaldra-zaad laat Tharn-vrouwen opzwellen en barsten: vruchtloze zwangerschappen.','Je ziet eerst een rotswand die ademt. Dan de littekens, die woorden zijn. Als ze praat, trilt je maag mee.'),
'orrim':('VOLK-orrim','Steenachtig: lichaam van ruwe zandsteen met kristaladers, geen zachte delen behalve de mond.','Rood-oker steen met glinsterende Sterrensteen-aders, geen haar, ogen als geslepen kristal.','2-2,5 m, enorm zwaar.','Kristalgroei die door de steen breekt; afbrokkelende ledematen bij ouderdom.','Geur van heet stof en bliksem; stem als schurend steen; onbeweeglijk tot ze plots bewegen.','Geen kleding; ingesleten slijptekens als sieraad.','Ouderen meer kristal, jongeren zachter zandsteen.','Geslachtloos tot de paring; dragers worden zwaarder en kristalliger.','Na steenoogst door de Orde: holtes en wonden die nooit sluiten.','Een rots die je aankijkt. In de aders glinstert het steen waar je merk van gemaakt is. Als hij praat, schuren zijn kaken.'),
'skerra':('VOLK-skerra','Gevleugeld: grote vleugels uit de schouderbladen (spanwijdte 5 m), holle botten, borstspier als een boeg.','Veren in grijs, zwart of roestrood tot halverwege de rug, huid strak, gouden roofvogelogen; haar overgaand in veren.','1,60-1,90 m, licht (50 kg).','Vleugels die bij inteelt scheef groeien; klauwachtige tenen.','Geur van wind en olie; scherpe, schreeuwende stem; schokkerig op de grond, prachtig in de lucht.','Leren harnassen, kettingen van gevallen veren als trofee.','Kliflijnen in kleur verschillend.','Vrouwen groter met bredere vleugels; mannen kleiner met felle kuifveren.','Geknipte of gebonden Skerra verliezen spieren en verstand.','Ze landt met een klap en vouwt een stuk hemel achter zich op. Haar ogen volgen je hartslag zoals een havik een muis. Op de grond lijkt ze te struikelen, maar ze is sneller dan jij.'),
'ves-lethi':('VOLK-ves-lethi','Vormveranderend: een glad, onvoltooid lichaam dat vaag menselijk is, met zachte botten.','Parelgrijze huid die kleur kan aannemen, haar dat groeit of verdwijnt, ogen zonder vaste kleur.','1,60-1,90 m, wisselend.','Bij te veel wisselen: gezichten die niet afkomen, twee monden, half man half vrouw blijven steken.','Geur van niets, of van wie ze nadoen; stem die verglijdt; bewegingen die net te vloeiend zijn.','Ze dragen wat de rol vraagt; onder elkaar een eenvoudig grijs kleed.','Oudere Ves-Lethi kunnen meer gedaanten; jongere alleen geslacht wisselen.','Geen vast verschil: in vrouwelijke fase zachter en ronder, in mannelijke fase zwaarder en vruchtbaar.','In de zegelschaduw raken ze vast in een vorm, of lopen ze uit als was.','Er klopt iets niet aan haar gezicht, maar je weet niet wat. Een week later is ze een man met dezelfde ogen. Ze ruikt naar je eigen huis.')}
F=['Lichaamsbouw','Huid, haar en ogen','Grootte','Afwijkingen','Geur, stem en beweging','Kleding en versiering','Variatie binnen het volk','Verschil man/vrouw','Uiterlijk bij inteelt of zegelschaduw','Eerste indruk voor een schrijver']
NM={'aelthir':'Aelthir','karruk':'Karrûk','dhurn':'Dhurn','saelmor':'Sael-mor','grauwen':'Grauwen','ishvar':'Ishvar','vathren':'Vathren','kluwer':'Kluwers','myrrhen':'Myrrhen','oevrin':'Oevrin','tharn':'Tharn','orrim':'Orrim','skerra':'Skerra','ves-lethi':'Ves-Lethi'}
for s,(vc,*vals) in U.items():
  add(f'UIT-VOLK-{s}','Volken uiterlijk',f'Uiterlijk van de {NM[s]}',' '.join(f'{k}: {v}' for k,v in zip(F,vals)),'uitgebreid uiterlijk per volk',vc)
# ---------- C: extreme kern per volk ----------
K={'aelthir':('Rekening-nachten van uren met ontzegging tot pijn (VOOR-ontzegging); doorschijnend genot: de partner kijkt naar het eigen hart dat in de ander klopt en drukt het met de hand na (VOOR-voyeurisme, VOOR-lichaam); geheugenruil: een Aelthir laat een mens een herinnering wegnemen in ruil voor één felle nacht en verliest zichzelf (VOOR-geest, VOOR-overgave).','Seks met snelheid: een Aelthir die binnen het uur klaarkomt is onteerd.',8,'VOOR-ontzegging;VOOR-voyeurisme;VOOR-geest;VOOR-overgave'),
'karruk':('Strijdontlading: de verliezer wordt na het gevecht door de winnares genomen, bloedend, voor het hele kamp (VOOR-ritueel-geweld, VOOR-exhibitionisme); kookhuid-seks: blaren die openbarsten tijdens de daad, pijn als bewijs (VOOR-pijn-genot, VOOR-walglust); vuurmoeder-ontlading: een kookkop wordt vastgebonden en door meerdere vuurmoeders ontladen tot hij niet meer gloeit (VOOR-bondage, VOOR-groep, VOOR-ontlading).','Tedere seks zonder strijd ervoor: dat geldt als laf.',7,'VOOR-ritueel-geweld;VOOR-pijn-genot;VOOR-walglust;VOOR-bondage;VOOR-groep;VOOR-ontlading'),
'dhurn':('Steenschuren: steenhuid over zachte huid tot die schaaft en bloedt (VOOR-slijpen, VOOR-pijn-genot); kokende baden: paren in water op de rand van verbranden (VOOR-uithouding); gildeverzegeling: het gilde bindt een paar in een schacht en metselt hen in voor een nacht met beperkte lucht (VOOR-bondage, VOOR-overgave).','Seks buiten het gildetoezicht; erger: fantasie met eigen lijn.',6,'VOOR-slijpen;VOOR-pijn-genot;VOOR-uithouding;VOOR-bondage;VOOR-overgave;VOOR-verboden'),
'saelmor':('Verdrinkingsparing tot bewusteloosheid en reanimatie met een kus (VOOR-overgave, VOOR-pijn-genot); kieuwspel: vingers en tongen in de kieuwen, het gevoeligste en gevaarlijkste orgaan (VOOR-lichaam); zoutkorst-breken: de partner breekt korsten open en likt het zout uit de wond (VOOR-walglust, VOOR-bloed).','Seks op het droge met één vaste partner: verraad aan het schip.',7,'VOOR-overgave;VOOR-pijn-genot;VOOR-lichaam;VOOR-walglust;VOOR-bloed'),
'grauwen':('Ontsluiering tot op de wond: een geliefde verkent elke vervorming met mond en hand, ook die de eigenaar zelf niet durft te zien (VOOR-walglust, VOOR-lichaam); misvormingsruil: twee Grauwen leggen hun vergroeiingen in elkaar, extra kootjes en botgroei als passende delen (VOOR-vergroeiing); angstlust-verkoop: Grauwen die zich laten huren door mensen die opgewonden raken van walging, als donker thema (VOOR-walglust, VOOR-handel).','Kinderen willen van een verwante: hun hele bestaan is de waarschuwing daartegen.',9,'VOOR-walglust;VOOR-lichaam;VOOR-vergroeiing;VOOR-handel;REGEL-verwantschapstaboe'),
'ishvar':('Geloftebranden: een eed wordt met een gloeiend goudstuk in de huid gebrand tijdens de climax (VOOR-ritueel-geweld, VOOR-binding); verbrandingslust: Ishvar-vrouwen die bewust gaven-zaad ontvangen om te voelen hoe hun huid blaast (VOOR-pijn-genot, VOOR-verboden); zonnenacht: dagen opgesloten in een donkere tent met één partner zonder eten, tot alleen nog lichaam over is (VOOR-ontzegging, VOOR-gevangenschap).','Een derde in het bed: het breekt de gelofte.',5,'VOOR-ritueel-geweld;VOOR-binding;VOOR-pijn-genot;VOOR-verboden;VOOR-ontzegging;VOOR-gevangenschap'),
'vathren':('Koortsontvangst: de gezel neemt meer zaad dan veilig is en brandt dagen in zegelkoorts (VOOR-pijn-genot, VOOR-overgave); hartsluiting: twee Vathren laten hun harten samenvallen tot een van beide bijna stopt (VOOR-geest); gloedlikken: lekkend zegellicht wordt van de littekens gelikt, verdovend en verslavend (VOOR-walglust, VOOR-lichaam).','Seks tijdens een lekpiek zonder ziener: men gelooft dat het de Zegel scheurt.',7,'VOOR-pijn-genot;VOOR-overgave;VOOR-geest;VOOR-walglust;VOOR-lichaam'),
'kluwer':('Korfparing: een volwassen mens die instemt wordt in de korfgeur opgenomen en voelt het genot van alle werksters tegelijk, dagenlang, zonder ik (VOOR-korf, VOOR-overgave); wasinplanting: de Broedmoeder legt via haar legbuis onvruchtbare was-eieren in een instemmende mens; ze lossen in dagen op tot een honingroes (VOOR-inplanting, VOOR-ei-dragen); darrendood-nacht: een dar paart tot hij sterft, voor de korf het hoogste offer (VOOR-ritueel-geweld, VOOR-afscheid).','Een werkster die alleen wil zijn met één partner, buiten de korfgeur: dat is een ik, en een ik is ziekte.',9,'VOOR-korf;VOOR-overgave;VOOR-inplanting;VOOR-ei-dragen;VOOR-ritueel-geweld;VOOR-afscheid'),
'myrrhen':('Sporenroes: partners ademen elkaars sporen in en verliezen dagen in gedeelde lustdromen (VOOR-sporenroes, VOOR-korf); draadvergroeiing: schimmeldraad groeit tussen twee lichamen tot ze een week aan elkaar vastzitten, met genot in elke beweging (VOOR-vergroeiing); rotbed: paren in een bed van verterend veen, en de zwam die over hun huid groeit en eet (VOOR-walglust, VOOR-inplanting).','Seks met vuur in de kamer, of met iemand die de zwam wil wegbranden.',10,'VOOR-sporenroes;VOOR-korf;VOOR-vergroeiing;VOOR-walglust;VOOR-inplanting'),
'oevrin':('Paaipoel: tientallen volwassenen paren tegelijk in één poel, alle afscheiding gemengd (VOOR-paaipoel, VOOR-groep, VOOR-anoniem); slijmlust: het dikke opwindingsslijm is verdovend en verslavend voor mensen (VOOR-slijm); keelzakomhulling: een Oevrin neemt hoofd en schouders van een instemmende partner in de keelzak, adem gecontroleerd, nooit dodelijk (VOOR-omhulling, VOOR-overgave); kuitdragen: mensen dragen kuit op de huid tot ze uitkomt en oplost (VOOR-ei-dragen).','Paren op het droge, en eigendom van een partner: "één poel, geen bezit".',8,'VOOR-paaipoel;VOOR-groep;VOOR-anoniem;VOOR-slijm;VOOR-omhulling;VOOR-overgave;VOOR-ei-dragen'),
'tharn':('Maatverschil: een volwassen mens als heel lichaam in de hand van een Tharn, als speelbal en aanbeden (VOOR-maatverschil, VOOR-overgave); zaadbad: Tharn-zaad in hoeveelheden waarin je kunt baden, met uren dierlijke kracht na (VOOR-overvloed); verplettering: een Tharn legt zich over de partner tot ademen een gunst wordt (VOOR-verplettering, VOOR-bondage).','Kleinmaking: een Tharn die zich door mensen laat vernederen en ketenen; voor een stervend volk het einde van eer.',6,'VOOR-maatverschil;VOOR-overgave;VOOR-overvloed;VOOR-verplettering;VOOR-bondage;VOOR-vernedering'),
'orrim':('Slijpparing: twee Orrim slijpen elkaar uren tot het stof hun kind wordt; met mensen tot de huid rauw is (VOOR-slijpen, VOOR-pijn-genot); versteening: een mens wordt met steenpasta bedekt en ligt dagen onbeweeglijk als heilig beeld, naar afspraak aangeraakt (VOOR-versteening, VOOR-bondage); kristalzaad: een Orrim laat een kristalkorrel onder de huid van een instemmende minnaar groeien als merk (VOOR-inplanting, VOOR-binding).','Steen eten van een andere Orrim: het opslokken van iemands kind en geheugen.',8,'VOOR-slijpen;VOOR-pijn-genot;VOOR-versteening;VOOR-bondage;VOOR-inplanting;VOOR-binding'),
'skerra':('Valparing: paren in vrije val vanaf de kliffen, loslaten op het laatste moment (VOOR-valparing); vleugelbinding: de partner bindt de vleugels, totale overgave en kwetsbaarheid (VOOR-vleugelbinding, VOOR-bondage); veerplukken: veren één voor één uittrekken tijdens de daad, bloed en pijn als liefdesbewijs (VOOR-ritueel-geweld, VOOR-pijn-genot); omhulling: de grote vrouw sluit haar partner in onder haar vleugels.','Paren op de grond, en vleugels voor altijd knippen.',6,'VOOR-valparing;VOOR-vleugelbinding;VOOR-bondage;VOOR-ritueel-geweld;VOOR-pijn-genot;VOOR-omhulling'),
'ves-lethi':('Vormwissel in de daad: van vrouw naar man in of om de partner (VOOR-vormwissel, VOOR-rolwissel); spiegelnacht: de Ves-Lethi neemt op verzoek de gedaante van een gewenste of verloren volwassene aan, donker thema van rouw en bedrog (VOOR-nabootsing); halfsmelting: twee Ves-Lethi laten hun zachte lichamen gedeeltelijk in elkaar opgaan en scheiden pas na uren (VOOR-vergroeiing, VOOR-walglust).','Een gedaante stelen van een levende zonder toestemming; nooit, ook niet als spel, de gedaante van een kind of dier: dat is ook voor hen het absolute taboe en het breekt hun lichaam.',8,'VOOR-vormwissel;VOOR-rolwissel;VOOR-nabootsing;VOOR-vergroeiing;VOOR-walglust')}
VK={'aelthir':'VOLK-aelthir','karruk':'VOLK-karrûk','dhurn':'VOLK-dhurn','saelmor':'VOLK-sael-mor','grauwen':'VOLK-grauwen','ishvar':'VOLK-ishvar','vathren':'VOLK-vathren'}
for s,(kern,taboe,walg,voor) in K.items():
  vc=VK.get(s,'VOLK-'+s)
  f=f"Extreme kern (voor dit volk normaal of heilig, intensiteit 4-5): {kern} Taboe-kink die zelfs het eigen volk schokt: {taboe} Walging voor buitenstaanders: {walg}/10. Koppeling: ritueel RIT-volk-{s}; voorkeuren {voor.replace(';',', ')}."+GRENS
  add(f'SEKS-VOLK-{s}-kern','Volken seksualiteit',f'{NM[s]}: extreme seksuele kern',f,'extreme kern vervangt/vult tamme seksuele cultuur aan',';'.join([vc,f'RIT-volk-{s}',voor]),intensiteit=5,afstoting=walg,functie='LUST;HECHT',aantrekking_bron='fetisj, heiligheid, angstlust',aantrekking=4)
for s in VK:
  c.execute("update canon set status='voorlopig, vervangen', reden=reden||' [Ronde 17: aangevuld/vervangen door SEKS-VOLK-'||?||'-kern]' where code=? and status='voorlopig'",(s,f'SEKS-VOLK-{s}'))
# rituelen per volk
R={'aelthir':'Nacht van de Rekening (verlengd): uren ontzegging, dan geheugenruil','karruk':'Vuurkamp-ontlading na het gevecht','dhurn':'Gildeverzegeling in de schacht','saelmor':'Springtij-verdrinkingsnacht','grauwen':'Volle Ontsluiering','ishvar':'Geloftebrand','vathren':'Koortsontvangst bij lekpiek','kluwer':'Korfopname: een mens drie nachten in de korfgeur','myrrhen':'Rotbed van de Grote Draad','oevrin':'Paaitij in de grote poel','tharn':'Dijknacht: de Tharn kiest een mens als gunst','orrim':'Slijpvonnis en Beeldnacht','skerra':'De Eerste Val (paarvlucht na de 18e verjaardag)','ves-lethi':'Spiegelnacht'}
for s,r in R.items():
  add(f'RIT-volk-{s}','Extreme rituelen',r,f"Ritueel van de {NM[s]}, vorm van hun extreme kern (zie SEKS-VOLK-{s}-kern). Wie: alleen volwassenen (18+) die vooraf instemmen, met een hoedster die stopt. Systeemfunctie: houdt de functie van het volk in stand (band, rang of voortplanting). Kink-schaal 5."+GRENS,'ritueel per volk',f'SEKS-VOLK-{s}-kern;{VK.get(s,"VOLK-"+s)}',intensiteit=5)
