add('NAV-wormwording','Lichaam en vervorming','Wormwording: de metamorfose van navigators',"Elke navigator die te lang in zegelschaduw, lekwater of Leegte werkt, verandert langzaam in een wormachtig wezen: de Zegel herschrijft het lichaam tot een orgaan dat alleen nog zegellijnen voelt. Hoe verder de worm, hoe beter de navigatie. Dat is de prijs en de reden waarom navigators onmisbaar en gevreesd zijn. Fasen: NAV-wormfase-1 tot -5, totaal 6 tot 20 jaar. Vrijwillig: de meeste lijnlezers kiezen het uit geloof of geld. Gedwongen: Varenne en Kharvos dwingen het af, als gelabeld donker thema. Grens: seksuele rollen alleen in fase 1 tot 3, zolang de navigator spreekt en instemt; fase 4 en 5 nooit seksueel, alleen verzorging. Koppeling: quest (Liora's gids), Orde, Varenne, Mirre, Kharvos."+GRENS,'navigators als wormen (Rogier)','FUNC-NAV;NAV-lijnlezer;NAV-zaadkompas;NAV-zoutloods;NAV-schaduwhonden;NAV-hartstem;ORDE-orde;HUI-varenne;HUI-mirre;REG-kharvos;PER-liora',functie='NAV;INFO',afstoting=8,aantrekking_bron='metamorfose-fetisj, ontzag, macht',aantrekking=3)
FA=[(1,'Week (0-2 jaar)','Huid wordt glad en vochtig, haar valt uit, tong verlengt; ledematen worden slap.','Volledig mens van geest; voelt de zegellijnen als jeuk en verlangen; hypergevoelige huid.','Pijn in de gewrichten, verlies van haar en status.','Bleek, glanzend, ogen te groot.','Geur van natte aarde; stem wordt fluisterend.','Mensen deinzen terug, sommigen raken opgewonden van de gladheid.','Zelfstandig, door een Orde-hoedster begeleid.',4,'metamorfose-fetisj, gevoeligheid',3),
(2,'Ring (2-5 jaar)','Ringvormige plooien over de romp, botten worden zachter, benen vergroeien deels; slijmklieren in de huid.','Denken helder, maar droomt in lijnen; seksualiteit verschuift naar huid en slijm.','Kan niet meer lopen zonder steun, verslaving aan zegelwater.','Geribbelde romp, glazige huid, mond rekbaar.','Zoete slijmgeur, zacht zuigend geluid bij bewegen.','Wormdienaressen (volwassen verzorgsters) aanbidden hen; Varenne-klanten betalen voor een nacht.','Verzorgd in een draagkuip; eigendom van Orde, Varenne of Mirre.',6,'walglust, macht, metamorfose',3),
(3,'Kruip (5-9 jaar)','Armen worden korte stompen, het lichaam strekt tot 3 meter, de mond wordt een ronde zuigmond met tong; ogen bijna blind.','Nog sprekend, met moeite; voelt het lek als hitte en honger; laatste fase waarin seks met instemming mogelijk is.','Afhankelijk van verzorging; afscheid van eigen naam.','Wit-roze worm met menselijk gezicht nog op de kop.','Geur van zuur en melk; neuriën dat door de grond trilt.','Pelgrims raken hen aan voor zegen; de begeerte is hier op zijn hoogst bij een kleine groep.','In zoutbaden of veenbakken, door wormdienaressen.',8,'angstlust, heiligheid',2),
(4,'Blind (9-14 jaar)','Gezicht vergroeit, geen ogen meer, huid doorzichtig; groeit tot 6 meter; graaft tunnels langs zegellijnen.','Geen woorden, alleen beelden die verzorgers via aanraking voelen; geen seksuele rol meer mogelijk.','Volledig verlies van menselijkheid naar buiten.','Doorschijnende reuzenworm met zichtbare aders van zegellicht.','Geur van ozon en rot; zwaar zuigen en kraken.','Alleen verzorging; navigatie door karavanen op zijn rug of in zijn tunnel.','Gedragen door Varenne-karavanen of Kharvos-legers.',9,'geen (alleen ontzag)',0),
(5,'Diepworm (14+ jaar)','Tot 20 meter, leeft in de grond rond Ves-Anath; voelt de hele Zegel; sterft als het lek groot wordt.','Een bewustzijn dat de Zegel zelf lijkt te horen; soms stuurt het beelden naar Vathren en lijnlezers.','Onomkeerbaar; niemand komt terug.','Een gang in de aarde die ademt.','Een diep zoemen dat dagen te horen is.','Vereerd als heilig, gevreesd als monster; geen seksuele rol.','Niemand bezit hen echt; Kharvos probeert ze te sturen.',10,'geen',0)]
